{"source":"def investigate(context, acquire):
    events = context.get('events', [])
    decoder = None
    count = 0
    status = 'open'
    for event in events:
        op = event.get('op')
        if op == 'feed':
            data = bytes(event.get('bytes', []))
            if decoder is None:
                decoder = acquire('utf-8')
            text, failed = decode_strict_incremental(decoder, data, False)
            if failed:
                status = 'error'
            else:
                count += len(text)
        elif op == 'finish':
            if decoder is None:
                decoder = acquire('utf-8')
            text, failed = decode_strict_incremental(decoder, b'', True)
            if failed:
                status = 'error'
            else:
                count += len(text)
                status = 'finished'
        elif op == 'reset':
            decoder = acquire('utf-8')
            count = 0
            status = 'open'
    return {'count': count, 'status': status}

def decode_strict_incremental(decoder, data, final):
    text = decoder.decode(data, final)
    return text, False
